629	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
630	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
631	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
632	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records the
633	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
634	     * {@link java.util.Optional#empty()} is returned.
635	     *
636	     * @param owner the owner being created, already carrying its normalized telephone and postcode
637	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
638	     */
639	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
640	        if (owner.getPostcode() == null) {
641	            return java.util.Optional.empty();
642	        }
643	        return this.clinicService.findAllOwners().stream()
644	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
645	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
646	                && owner.getPostcode().equals(existing.getPostcode())
647	                && !owner.getTelephone().equals(existing.getTelephone()))
648	            .findFirst();
