678	    /**
679	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
680	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
681	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
682	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
683	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
684	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
685	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
686	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
687	     *
688	     * @param telephone the submitted telephone value
689	     * @return the normalized E.164 telephone
690	     */
691	    private String normalizeTelephone(String telephone) {
692	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
693	        String e164;
694	        if (cleaned.startsWith("+")) {
695	            e164 = "+" + cleaned.substring(1);
696	        } else {
697	            String national = cleaned;
698	            if (national.startsWith("0")) {
699	                national = national.substring(1);
700	            }
701	            e164 = "+61" + national;
702	        }
703	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
704	            throw new InvalidFieldsException(List.of("telephone"));
705	        }
706	        validateNationalNumberLength(e164);
707	        return e164;
708	    }
709	
710	    /**
711	     * Validates the national-number length of an already syntactically valid E.164 telephone
712	     * against its country code. When the number carries a country code this application recognizes
713	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
714	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
715	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
716	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
717	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
718	     * that is not recognized carries no per-country length rule and is left to the general
719	     * 8-to-15-digit E.164 check.
720	     *
721	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
722	     */
723	    private void validateNationalNumberLength(String e164) {
724	        String countryCode = Owner.countryCodeOf(e164);
725	        if (countryCode == null) {
726	            return;
727	        }
728	        int nationalLength = e164.length() - 1 - countryCode.length();
729	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
730	            throw new InvalidFieldsException(List.of("telephone"));
731	        }
732	    }
