734	    /**
735	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
736	     * and a domain containing at least one dot, none of the parts holding whitespace or a
737	     * second {@code @}.
738	     */
739	    private static final java.util.regex.Pattern EMAIL_PATTERN =
740	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
741	
742	    /**
743	     * Disposable email domains an owner may not register with. An email whose domain (compared
744	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
745	     */
746	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
747	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
748	
749	    /**
750	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
751	     * accepted and returned unchanged. When present it must be a syntactically valid address
752	     * whose domain is not on the disposable-domain blocklist (see
753	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
754	     * present but syntactically invalid or on a disposable domain an
755	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
756	     * response naming the {@code email} field.
757	     *
758	     * @param email the submitted email value, or {@code null} when omitted
759	     * @return the lower-cased email, or {@code null} when none was supplied
760	     */
761	    private String normalizeEmail(String email) {
762	        if (email == null) {
763	            return null;
764	        }
765	        String trimmed = email.trim();
766	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
767	            throw new InvalidFieldsException(List.of("email"));
768	        }
769	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
770	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
771	            throw new InvalidFieldsException(List.of("email"));
772	        }
773	        return canonicalEmail(trimmed);
774	    }
