889	     * @param lastName the household's last name
890	     * @param postcode the household's postcode, or {@code null} when the owner has none
891	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
892	     */
893	    private String householdIdFor(String lastName, String postcode) {
894	        if (postcode == null) {
