916	    /**
917	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
918	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
919	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
920	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
921	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
922	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
923	     * an {@link IllegalStateException} is thrown.
924	     *
925	     * @param input the string to hash
926	     * @param hexChars the number of leading upper-case hex characters to return
927	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
928	     */
929	    private String shaHex(String input, int hexChars) {
930	        try {
931	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
932	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
933	            StringBuilder sb = new StringBuilder();
934	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
935	                sb.append(String.format("%02X", digest[i]));
936	            }
937	            return sb.substring(0, hexChars);
938	        }
939	        catch (java.security.NoSuchAlgorithmException e) {
940	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
941	        }
942	    }
