1005	        return value.trim().replaceAll("\\s+", " ");
1006	    }
1007	
1008	    /**
1009	     * Common street-type abbreviations expanded during address normalization, keyed by their
1010	     * upper-cased token.
1011	     */
1012	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1013	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1014	
1015	    /**
1016	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1017	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1018	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1019	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1020	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1021	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1022	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1023	     * everywhere an address is stored or compared.
1024	     *
1025	     * @param address the submitted address value, or {@code null}
1026	     * @return the normalized address, never {@code null}
1027	     */
1028	    private String normalizeAddress(String address) {
1029	        if (address == null) {
1030	            return "";
1031	        }
1032	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1033	        if (collapsed.isEmpty()) {
1034	            return "";
1035	        }
1036	        String[] tokens = collapsed.split(" ");
1037	        StringBuilder sb = new StringBuilder(collapsed.length());
1038	        for (int i = 0; i < tokens.length; i++) {
1039	            if (i > 0) {
1040	                sb.append(' ');
1041	            }
1042	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1043	        }
1044	        return sb.toString();
1045	    }
1046	}
